apiVersion: apps/v1
kind: Deployment
metadata: { name: api }
spec:
  replicas: 3
  selector: { matchLabels: { app: api } }
  template:
    metadata: { labels: { app: api } }
    spec:
      containers:
      - name: api
        image: registre/api:1.4.2
        resources:
          requests: { cpu: 250m, memory: 256Mi }
          limits: { memory: 512Mi }
